<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class AdminUser extends Authenticatable { use HasFactory, Notifiable; protected $guarded=[]; protected $hidden=['password','remember_token']; protected function casts():array{return ['password'=>'hashed','last_login_at'=>'datetime'];} public function roles():BelongsToMany{return $this->belongsToMany(Role::class,'role_user');} public function auditLogs():HasMany{return $this->hasMany(AuditLog::class);} public function assignedTickets():HasMany{return $this->hasMany(SupportTicket::class,'assigned_admin_id');} public function hasPermission(string $permission):bool{return $this->roles()->whereHas('permissions',fn($q)=>$q->where('slug',$permission))->exists();} }
